// Fallback used if a row's Category doesn't match anything above (e.g. blank or a genuine typo
// that normalization below can't fix). Change this to a real category name to enable a fallback
// instead of erroring, or leave null to fail loudly.
const DEFAULT_CATEGORY = null;

// Matches regardless of case and regardless of spacing differences, e.g.
// "LOG-Warehouse", "LOG- Warehouse", "log -warehouse" all resolve to the same entry.
// It does NOT fix genuine misspellings (e.g. "Manuf-Machinry") -- those still need
// either a sheet correction or DEFAULT_CATEGORY above.
const normalizeKey = (s) => (s || "").toString().trim().toLowerCase().replace(/\s+/g, "");

const NORMALIZED_MAP = {};
for (const [key, value] of Object.entries(CONTENT_MAP)) {
  NORMALIZED_MAP[normalizeKey(key)] = value;
}

const results = [];
for (const item of $input.all()) {
  const d = item.json;
  const rawCategory = d["Category"] || "";
  const template =
    NORMALIZED_MAP[normalizeKey(rawCategory)] ||
    (DEFAULT_CATEGORY ? NORMALIZED_MAP[normalizeKey(DEFAULT_CATEGORY)] : null);

  if (!template) {
    throw new Error(`No email content found for Category "${rawCategory}" (row: ${d["Email"] || "unknown"}). Check for a typo in the Category column, or set DEFAULT_CATEGORY above.`);
  }

  let subject = template.subject.replace(/{{Company}}/g, d["Company"] || "");
  let message = template.message
    .replace(/{{Name}}/g, d["Name"] || "")
    .replace(/{{Company}}/g, d["Company"] || "")
    .replace(/{{City}}/g, d["City"] || "");

  results.push({ json: { ...d, subject, message } });
}

return results;
